namespace Eleph\SQLite\Manifest;

use Eleph\SQLite\Sql\{Column, EdgePlacement, Index, TableSchema};
use Eleph\Runtime\Storage\RelationKind;

return new StorageManifest(
    tables: [
        'Owner' => new TableSchema(
            'owner',
            [
                'id' => new Column('id', 'INTEGER', false, true, null),
                'name' => new Column('name', 'TEXT', true, false, null),
                'rank' => new Column('rank', 'INTEGER', true, false, null),
                'target_id' => new Column('target_id', 'INTEGER', true, false, null),
            ],
            [
                'owner_target_id_uniq' => new Index('owner_target_id_uniq', ['target_id'], true),
            ],
            'id',
        ),
        'Target' => new TableSchema(
            'target',
            [
                'id' => new Column('id', 'INTEGER', false, true, null),
                'name' => new Column('name', 'TEXT', true, false, null),
                'rank' => new Column('rank', 'INTEGER', true, false, null),
            ],
            [

            ],
            'id',
        ),
    ],
    placements: [
        'Owner.target' => new EdgePlacement('Owner', 'target', 'Target', RelationKind::OneToOne, 'owner', 'target_id', null, 'target'),
    ],
    columns: [
        'Owner' => ['name' => 'name', 'rank' => 'rank'],
        'Target' => ['name' => 'name', 'rank' => 'rank'],
    ],
    joinTables: [

    ],
);

/**
 * Explicit initial installation. Existing tables cause a failure and rollback.
 * Evolving a populated database requires a reviewed application migration.
 * Use the same prefix when loading StorageManifest::withPrefix().
 */
return static function (\PDO $database, string $prefix = ''): void {
    if ($database->getAttribute(\PDO::ATTR_DRIVER_NAME) !== 'sqlite') {
        throw new \InvalidArgumentException('This installer requires PDO SQLite.');
    }
    if ($prefix !== '' && !preg_match('/^[A-Za-z_][A-Za-z0-9_]*$/D', $prefix)) {
        throw new \InvalidArgumentException('Invalid SQLite table prefix.');
    }
    if ($database->inTransaction()) {
        throw new \LogicException('Run the initial installer outside an existing transaction.');
    }
    $database->exec('PRAGMA foreign_keys = ON');
    $table = static fn (string $name): string => '"' . $prefix . $name . '"';
    $statements = [
        'CREATE TABLE ' . $table('owner') . ' (
    ' . '"id" INTEGER PRIMARY KEY AUTOINCREMENT' . ',
    ' . '"name" TEXT' . ',
    ' . '"rank" INTEGER' . ',
    ' . '"target_id" INTEGER' . ' REFERENCES ' . $table('target') . '("id") ON DELETE RESTRICT' . '
)',
        'CREATE UNIQUE INDEX ' . $table('owner_target_id_uniq') . ' ON ' . $table('owner') . ' ("target_id")',
        'CREATE TABLE ' . $table('target') . ' (
    ' . '"id" INTEGER PRIMARY KEY AUTOINCREMENT' . ',
    ' . '"name" TEXT' . ',
    ' . '"rank" INTEGER' . '
)',
    ];
    $database->beginTransaction();
    try {
        foreach ($statements as $sql) {
            if ($database->exec($sql) === false) {
                $detail = $database->errorInfo()[2] ?? null;
                throw new \RuntimeException('SQLite schema installation failed: ' . (is_string($detail) ? $detail : 'unknown error'));
            }
        }
        $database->commit();
    } catch (\Throwable $error) {
        $database->rollBack();
        throw $error;
    }
};
